    fun handleStale(ex: WorkoutStaleException): ProblemDetail =
        ProblemDetail
            .forStatusAndDetail(HttpStatus.CONFLICT, ex.message ?: "Workout changed")
            .apply { setProperty("etag", ETagWebConverter.toETag(ex.currentUpdatedAt)) }

    /**
     * A stale floor set replay (KAN-757, decision `value-compare-and-set`): nothing was written.
     * `current` is the stored set in the request's own wire shape, `updatedBy` names who got there
     * first (`{id, displayName}`, omitted for a set no PATCH has stamped yet) and `updatedAt` when
     * the stamp exists (omitted otherwise, as with the transition actors above).
     */
    @ExceptionHandler(WorkoutSetChangedException::class)
    fun handleSetChanged(ex: WorkoutSetChangedException): ProblemDetail =
        ProblemDetail
            .forStatusAndDetail(HttpStatus.CONFLICT, "This set was changed on another phone.")
            .apply {
                setProperty("code", "set_changed")
                setProperty(
                    "current",
                    mapOf(
                        "weight" to SetWeightWebConverter.toDto(ex.current.weight),
                        "effort" to SetEffortWebConverter.toDto(ex.current.effort),
                        "confirmed" to (ex.current.confirmedAt != null),
                    ),
                )
                ex.current.updatedBy?.let { setProperty("updatedBy", actorOf(it)) }
                ex.current.updatedAt?.let { setProperty("updatedAt", it) }
            }
